import React, { useState } from 'react';
import { PRODUCTS } from '../../data/products';
import ProductCard from '../../components/product/ProductCard/ProductCard';
import styles from './CollectionsPage.module.css';

const CollectionsPage = () => {
  const [selectedCollection, setSelectedCollection] = useState('All');

  // Define collections
  const collections = [
    {
      id: 'all',
      name: 'All Collections',
      description: 'Browse our entire curated collection',
    },
    {
      id: 'everyday',
      name: 'Everyday Luxe',
      description: 'Wearable gems for daily elegance',
      filter: (p) => ['Necklaces', 'Earrings', 'Bracelets'].includes(p.category),
    },
    {
      id: 'statement',
      name: 'Statement Pieces',
      description: 'Bold, iconic designs that turn heads',
      filter: (p) => p.rating >= 4.8,
    },
    {
      id: 'rings',
      name: 'Ring Collection',
      description: 'From everyday to engagement',
      filter: (p) => p.category === 'Rings',
    },
    {
      id: 'traditional',
      name: 'Traditional Indian',
      description: 'Modern take on timeless designs',
      filter: (p) => p.category === 'Mangalsutra',
    },
    {
      id: 'mens',
      name: 'Men\'s Collection',
      description: 'Sophisticated pieces for the modern man',
      filter: (p) => p.category === 'Mens',
    },
  ];

  const filteredProducts =
    selectedCollection === 'All'
      ? PRODUCTS
      : PRODUCTS.filter(collections.find((c) => c.id === selectedCollection)?.filter || (() => true));

  return (
    <div className={styles.page}>
      {/* Page Header */}
      <section className={styles.pageHeader}>
        <div className={styles.headerContent}>
          <h1 className={styles.title}>Collections</h1>
          <p className={styles.subtitle}>
            Explore our thoughtfully curated collections designed for every style and occasion.
          </p>
        </div>
      </section>

      {/* Collection Tabs */}
      <section className={styles.tabsSection}>
        <div className={styles.tabsContainer}>
          {collections.map((collection) => (
            <button
              key={collection.id}
              className={`${styles.tab} ${
                selectedCollection === collection.id ? styles['tab--active'] : ''
              }`}
              onClick={() => setSelectedCollection(collection.id)}
            >
              {collection.name}
            </button>
          ))}
        </div>
      </section>

      {/* Products Grid */}
      <div className={styles.container}>
        {filteredProducts.length > 0 ? (
          <>
            <div className={styles.collectionInfo}>
              <h2 className={styles.collectionTitle}>
                {collections.find((c) => c.id === selectedCollection)?.name || 'All Collections'}
              </h2>
              <p className={styles.collectionDesc}>
                {collections.find((c) => c.id === selectedCollection)?.description}
              </p>
            </div>
            <div className={styles.productsGrid}>
              {filteredProducts.map((product) => (
                <ProductCard key={product.id} product={product} />
              ))}
            </div>
          </>
        ) : (
          <div className={styles.noResults}>
            <p>No products in this collection yet.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default CollectionsPage;
